using System.Collections;
using System.Collections.Concurrent;
using System.Reflection;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;

namespace Masterly.NonEmptyList.NewtonsoftJson;

/// <summary>
/// A single Json.NET converter for every non-empty type: <see cref="NonEmptyList{T}"/>, <see cref="ImmutableNonEmptyList{T}"/>,
/// <see cref="NonEmptySet{T}"/>, <see cref="ConstrainedList{T, TConstraint}"/>, <see cref="NonEmptyDictionary{TKey, TValue}"/>,
/// <see cref="NonEmptyString"/> and classes generated by <c>[NonEmptyCollection]</c>. Lists serialize as arrays,
/// dictionaries as objects, strings as strings. Empty input is rejected with a <see cref="JsonSerializationException"/>.
/// </summary>
public sealed class NonEmptyJsonConverter : JsonConverter
{
    private static readonly ConcurrentDictionary<Type, Shape?> Shapes = new();

    /// <inheritdoc />
    public override bool CanConvert(Type objectType)
    {
        Type underlying = Nullable.GetUnderlyingType(objectType) ?? objectType;
        return underlying == typeof(NonEmptyString) || GetShape(underlying) is not null;
    }

    /// <inheritdoc />
    public override object? ReadJson(JsonReader reader, Type objectType, object? existingValue, JsonSerializer serializer)
    {
        if (reader.TokenType == JsonToken.Null)
        {
            if (objectType == typeof(NonEmptyString))
                throw Fail(reader, "NonEmptyString cannot be null");
            return null;
        }

        Type underlying = Nullable.GetUnderlyingType(objectType) ?? objectType;

        if (underlying == typeof(NonEmptyString))
        {
            if (reader.TokenType != JsonToken.String)
                throw Fail(reader, $"Expected a string for NonEmptyString but found {reader.TokenType}");

            return NonEmptyString.TryCreate((string?)reader.Value, out NonEmptyString result)
                ? result
                : throw Fail(reader, "NonEmptyString cannot be empty or whitespace");
        }

        Shape shape = GetShape(underlying) ?? throw Fail(reader, $"{objectType} is not a non-empty type");

        object? materialized = serializer.Deserialize(reader, shape.IntermediateType);
        if (materialized is null || ((ICollection)materialized).Count == 0)
            throw Fail(reader, $"{DisplayName(underlying)} cannot be empty");

        if (!shape.IsDictionary && ((IList)materialized).Cast<object?>().Any(static x => x is null))
            throw Fail(reader, $"{DisplayName(underlying)} cannot contain null elements");

        try
        {
            return InvokeFrom(shape.From, materialized);
        }
        catch (Exception ex) when (ex is ArgumentException or InvalidOperationException)
        {
            throw Fail(reader, $"{DisplayName(underlying)}: {ex.Message}", ex);
        }
    }

    // "NonEmptyList" rather than the CLR name "NonEmptyList`1".
    private static string DisplayName(Type type)
    {
        int tick = type.Name.IndexOf('`');
        return tick < 0 ? type.Name : type.Name[..tick];
    }

    // Same message shape and Path/LineNumber/LinePosition properties as the exceptions Json.NET raises itself.
    private static JsonSerializationException Fail(JsonReader reader, string message, Exception? innerException = null)
    {
        string path = reader.Path;
        if (reader is IJsonLineInfo lineInfo && lineInfo.HasLineInfo())
        {
            return new JsonSerializationException(
                $"{message}. Path '{path}', line {lineInfo.LineNumber}, position {lineInfo.LinePosition}.",
                path, lineInfo.LineNumber, lineInfo.LinePosition, innerException);
        }

        return new JsonSerializationException($"{message}. Path '{path}'.", path, 0, 0, innerException);
    }

    /// <inheritdoc />
    public override void WriteJson(JsonWriter writer, object? value, JsonSerializer serializer)
    {
        switch (value)
        {
            case null:
                writer.WriteNull();
                return;

            case NonEmptyString s:
                writer.WriteValue(s.Value);
                return;

            case IDictionary dictionary:
                serializer.Serialize(writer, dictionary);
                return;

            case IEnumerable sequence when GetShape(value.GetType()) is { IsDictionary: true }:
                {
                    // NonEmptyDictionary<,> implements only the generic IDictionary<,>; copy it so Json.NET writes an object.
                    object plain = value.GetType().GetMethod("ToDictionary", Type.EmptyTypes)!.Invoke(value, null)!;
                    serializer.Serialize(writer, plain);
                    return;
                }

            case IEnumerable sequence:
                writer.WriteStartArray();
                foreach (object? item in sequence)
                    serializer.Serialize(writer, item);
                writer.WriteEndArray();
                return;

            default:
                throw new JsonSerializationException($"{value.GetType()} is not a non-empty type");
        }
    }

    private static Shape? GetShape(Type type) => Shapes.GetOrAdd(type, static t => BuildShape(t));

    private static Shape? BuildShape(Type type)
    {
        for (Type? current = type; current is not null && current != typeof(object); current = current.BaseType)
        {
            if (!current.IsGenericType)
                continue;

            Type definition = current.GetGenericTypeDefinition();
            Type[] args = current.GetGenericArguments();

            if (definition == typeof(NonEmptyDictionary<,>))
            {
                Type pairEnumerable = typeof(IEnumerable<>).MakeGenericType(typeof(KeyValuePair<,>).MakeGenericType(args[0], args[1]));
                return new Shape(typeof(Dictionary<,>).MakeGenericType(args[0], args[1]), true, FindFrom(type, pairEnumerable));
            }

            if (definition == typeof(NonEmptyList<>) || definition == typeof(ImmutableNonEmptyList<>) ||
                definition == typeof(NonEmptySet<>) || definition == typeof(ConstrainedList<,>))
            {
                return new Shape(typeof(List<>).MakeGenericType(args[0]), false, FindFrom(type, typeof(IEnumerable<>).MakeGenericType(args[0])));
            }
        }

        return null;
    }

    private static MethodInfo FindFrom(Type type, Type parameterType)
    {
        for (Type? current = type; current is not null; current = current.BaseType)
        {
            MethodInfo? method = current
                .GetMethods(BindingFlags.Public | BindingFlags.Static | BindingFlags.DeclaredOnly)
                .FirstOrDefault(m => m.Name == "From" && m.GetParameters() is { Length: >= 1 } ps && ps[0].ParameterType == parameterType &&
                                     ps.Skip(1).All(p => p.IsOptional) && m.ReturnType.IsAssignableTo(type));
            if (method is not null)
                return method;
        }

        throw new JsonSerializationException($"{type} does not expose a static From({parameterType}) factory");
    }


    private static object? InvokeFrom(MethodInfo from, object argument)
    {
        ParameterInfo[] parameters = from.GetParameters();
        object?[] args = new object?[parameters.Length];
        args[0] = argument;
        for (int i = 1; i < parameters.Length; i++)
            args[i] = parameters[i].HasDefaultValue ? parameters[i].DefaultValue : null;
        // Unwrapped, so a factory's own exception surfaces as itself rather than as TargetInvocationException.
        return from.Invoke(null, BindingFlags.DoNotWrapExceptions, null, args, null);
    }

    private sealed record Shape(Type IntermediateType, bool IsDictionary, MethodInfo From);
}

/// <summary>Registration helpers.</summary>
public static class NonEmptyJsonConverterExtensions
{
    /// <summary>Adds the non-empty converter to the settings. Idempotent.</summary>
    public static JsonSerializerSettings AddNonEmptyConverters(this JsonSerializerSettings settings)
    {
        ArgumentNullException.ThrowIfNull(settings);
        if (!settings.Converters.Any(static c => c is NonEmptyJsonConverter))
            settings.Converters.Add(new NonEmptyJsonConverter());
        return settings;
    }

    /// <summary>Adds the non-empty converter to a serializer. Idempotent.</summary>
    public static JsonSerializer AddNonEmptyConverters(this JsonSerializer serializer)
    {
        ArgumentNullException.ThrowIfNull(serializer);
        if (!serializer.Converters.Any(static c => c is NonEmptyJsonConverter))
            serializer.Converters.Add(new NonEmptyJsonConverter());
        return serializer;
    }

    /// <summary>Serializes with the non-empty converter registered.</summary>
    public static string SerializeNonEmpty(object? value, JsonSerializerSettings? settings = null)
        => JsonConvert.SerializeObject(value, (settings ?? new JsonSerializerSettings()).AddNonEmptyConverters());

    /// <summary>Deserializes with the non-empty converter registered.</summary>
    public static T? DeserializeNonEmpty<T>(string json, JsonSerializerSettings? settings = null)
        => JsonConvert.DeserializeObject<T>(json, (settings ?? new JsonSerializerSettings()).AddNonEmptyConverters());

    /// <summary>Converts a <see cref="JToken"/> to a non-empty type.</summary>
    public static T? ToNonEmpty<T>(this JToken token)
    {
        ArgumentNullException.ThrowIfNull(token);
        return token.ToObject<T>(new JsonSerializer().AddNonEmptyConverters());
    }
}
